<div class="breadcrumb"><a href="<?= url('/dashboard#curso-'.rawurlencode($course['slug'])) ?>">Mapa da Jornada</a><span>/</span><a href="<?= url('/aulas/'.rawurlencode($course['slug']).'/'.rawurlencode($module['slug']).'/'.rawurlencode($lesson['slug'])) ?>"><?= e($lesson['title']) ?></a></div>
<div class="page-heading"><span class="page-kicker">Challenge Mode</span><h1>Exercício de fixação</h1><p><?= e($exercise['title']) ?></p><?php if(!empty($isGuest)):?><span class="badge">👾 tentativa sem gravação</span><?php endif;?></div>
<?php if(is_array($result)):$resultCorrect=(bool)($result['correct']??false);?><div class="result-banner <?= $resultCorrect?'':'is-wrong' ?>"><?php if($resultCorrect):?>✓ Resposta certa!<?= !empty($result['guest'])?' Resultado desta tentativa não foi salvo.':(((int)($result['total_xp']??0)>0)?' +'.(int)$result['total_xp'].' XP.':'') ?><?php else:?>✗ Não foi dessa vez. Revise a aula e tente novamente.<?= !empty($result['guest'])?' Nada foi gravado.':'' ?><?php endif;?></div>
