<div class="panel" style="max-width:78ch;"><p style="margin-bottom:20px;"><?= e($exercise['question']??'') ?></p><form action="<?= url('/exercicios/'.rawurlencode($course['slug']).'/'.rawurlencode($module['slug']).'/'.rawurlencode($lesson['slug'])) ?>" method="POST"><?= csrf_field() ?>
<?php if(in_array($exercise['exercise_type'],['multiple_choice','true_false'],true)):?><?php if(empty($options)):?><div class="alert alert-error">Este exercício está sem opções válidas. Informe o administrador.</div><?php else:?><?php foreach($options as $letra=>$texto):?><label class="quiz-option"><input type="radio" name="resposta" value="<?= e((string)$letra) ?>" <?= isset($answer)&&$answer===(string)$letra?'checked':'' ?> required><span><strong><?= e(strtoupper((string)$letra)) ?>)</strong> <?= e((string)$texto) ?></span></label><?php endforeach;?><?php endif;?>
<?php else:?><div class="field"><label for="resposta">Sua resposta</label><textarea id="resposta" name="resposta" rows="8" maxlength="10000" class="code-input" required><?= isset($answer)?e((string)$answer):'' ?></textarea></div><?php endif;?>
<?php if(!in_array($exercise['exercise_type'],['multiple_choice','true_false'],true)||!empty($options)):?><button type="submit" class="btn btn-primary">Enviar resposta<?= !empty($isGuest)?' (não salvar)':'' ?></button><?php endif;?></form></div>
